import math
from collections import Counter

def euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def knn_predict(train_X, train_y, query, k):
    pairs = [(euclidean(x, query), label) for x, label in zip(train_X, train_y)]
    nearest = sorted(pairs)[:k]
    return Counter(label for d, label in nearest).most_common(1)[0][0]

import numpy as np

rng = np.random.default_rng(0)
X = np.vstack([rng.normal([-1, 0], 0.6, (30, 2)), rng.normal([1, 0], 0.6, (30, 2))])
y = np.array([0] * 30 + [1] * 30)

def pairwise_dist(Q, X):
    diff = Q[:, None, :] - X[None, :, :]
    return np.sqrt((diff ** 2).sum(axis=-1))

def knn_classify(Q, X, y, k):
    D = pairwise_dist(Q, X)
    idx = np.argsort(D, axis=1)[:, :k]
    return (y[idx].mean(axis=1) > 0.5).astype(int)
